/** The days from `fromDay` up to but not including `toDay` on which the route is not open, in rising order. */
export function closedDays(register: Register, route: Route, fromDay: number, toDay: number): number[] {
    const days: number[] = [];
    for (let day = fromDay; day < toDay; day++) {
        if (!routeOpen(register, route, day)) {
            days.push(day);
        }
    }
    return days;
}

